# Dumps the memory behind metal_compositor_map() in the running WindowServer (three levels of pointers, 8 words each) to /Users/Shared/ws_mapdump2.txt: the keys the Metal compositors are
# stored under (dtrace pid provider, root, a few seconds; move a window so that the map is used). The D program below was generated by a small script (nested copyin of 64 bytes).
# Run: sudo sh -c 'nohup sh /Users/Shared/ws_mapdump2.sh >/dev/null 2>&1 &'
OUT=/Users/Shared/ws_mapdump2.txt
ERR=/Users/Shared/ws_mapdump2_err.txt
D=/Users/Shared/ws_mapdump2.d
rm -f $OUT $ERR
PID=$(pgrep -x WindowServer | head -1)
echo "start $(date) WindowServer $PID" > $ERR
cat > $D <<'EOD'
int done;
pid$target:SkyLight:*metal_compositor_map*:return /!done/ { this->b = (uint64_t *)copyin(arg1, 32); this->n = this->b[2]; }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->n > 0x600000000000/ { this->nb = (uint64_t *)copyin(this->n, 64); this->v = this->nb[3]; printf("NODE %x key %x value %x\n", this->n, this->nb[2], this->v); }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->n > 0x600000000000/ { this->nb = (uint64_t *)copyin(this->n, 64); this->v = this->nb[3]; this->w = (uint64_t *)copyin(this->v + 0, 64); printf("VAL+0x%x: %x %x %x %x %x %x %x %x\n", 0, this->w[0], this->w[1], this->w[2], this->w[3], this->w[4], this->w[5], this->w[6], this->w[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->n > 0x600000000000/ { this->nb = (uint64_t *)copyin(this->n, 64); this->v = this->nb[3]; this->w = (uint64_t *)copyin(this->v + 64, 64); printf("VAL+0x%x: %x %x %x %x %x %x %x %x\n", 64, this->w[0], this->w[1], this->w[2], this->w[3], this->w[4], this->w[5], this->w[6], this->w[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->n > 0x600000000000/ { this->nb = (uint64_t *)copyin(this->n, 64); this->v = this->nb[3]; this->w = (uint64_t *)copyin(this->v + 128, 64); printf("VAL+0x%x: %x %x %x %x %x %x %x %x\n", 128, this->w[0], this->w[1], this->w[2], this->w[3], this->w[4], this->w[5], this->w[6], this->w[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->n > 0x600000000000/ { this->nb = (uint64_t *)copyin(this->n, 64); this->v = this->nb[3]; this->w = (uint64_t *)copyin(this->v + 192, 64); printf("VAL+0x%x: %x %x %x %x %x %x %x %x\n", 192, this->w[0], this->w[1], this->w[2], this->w[3], this->w[4], this->w[5], this->w[6], this->w[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done && this->n > 0x600000000000/ { this->nb = (uint64_t *)copyin(this->n, 64); this->v = this->nb[3]; this->w = (uint64_t *)copyin(this->v, 64); this->o = this->w[2]; this->ob = (uint64_t *)copyin(this->o, 64); printf("OBJ@+0x10 %x: %x %x %x %x %x %x %x %x\n", this->o, this->ob[0], this->ob[1], this->ob[2], this->ob[3], this->ob[4], this->ob[5], this->ob[6], this->ob[7]); }
pid$target:SkyLight:*metal_compositor_map*:return /!done/ { done = 1; }
pid$target:SkyLight:*WSGetCompositorMetal*:return { printf("WSGetCompositorMetal -> %x\n", arg1); }
pid$target:SkyLight:*WSGetCompositorForAccelerator*:return { printf("WSGetCompositorForAccelerator -> %x\n", arg1); }
tick-4s { exit(0); }
EOD
dtrace -Z -x dynvarsize=8m -p $PID -q -o $OUT -s $D >> $ERR 2>&1
chmod 644 $OUT $ERR
